import type { Aisle, CatalogEntry, Measure } from "./types";

type Extra = Partial<Omit<CatalogEntry, "id" | "aisle" | "measure" | "aliases">>;

function e(id: string, aisle: Aisle, measure: Measure, aliases: string, extra: Extra = {}): CatalogEntry {
  return {
    id,
    name: extra.name ?? id.replaceAll("-", " "),
    aliases: aliases ? aliases.split("|") : [],
    aisle,
    measure,
    ...extra,
  };
}

const P = "Produce";
const B = "Bakery";
const M = "Meat";
const FS = "Fish & Seafood";
const D = "Dairy";
const EG = "Eggs";
const T = "Pantry";
const BK = "Baking";
const S = "Spices";
const F = "Frozen";
const V = "Beverages";
const H = "Household";

const herb = (id: string, aliases: string, extra: Extra = {}): CatalogEntry =>
  e(id, P, "piece", aliases, { pieceUnit: "bunch", pieceGrams: 30, density: 0.1, unitGrams: { sprig: 3, handful: 15, leaf: 0.5, stalk: 3 }, ...extra });
const spice = (id: string, aliases: string, extra: Extra = {}): CatalogEntry =>
  e(id, S, "g", aliases, { staple: true, density: 0.5, ...extra });
const sauce = (id: string, aliases: string, extra: Extra = {}): CatalogEntry =>
  e(id, T, "ml", aliases, { staple: true, density: 1.1, ...extra });
const canned = (id: string, aliases: string, grams = 400, extra: Extra & { measure?: Measure } = {}): CatalogEntry =>
  e(id, T, extra.measure ?? "piece", aliases, { pieceUnit: "can", pieceGrams: grams, ...extra });

